function validate([queries, m]) {
  if (!Number.isInteger(m) || m < 1 || m > 1000) return 'm must be between 1 and 1000.';
  if (!Array.isArray(queries) || queries.length < 1 || queries.length > m) return 'queries needs between 1 and m values.';
  if (queries.some(q => !Number.isInteger(q) || q < 1 || q > m)) return 'Each query is an integer from 1 to m.';
  return null;
}

