function processQueries(queries, m) {
  const perm = [];
  for (let value = 1; value <= m; value++) {
    perm.push(value);
  }
  const result = [];

  for (const query of queries) {
    let position = 0;
    while (perm[position] !== query) {
      position++;
    }
    result.push(position);
    for (let k = position; k > 0; k--) {
      perm[k] = perm[k - 1];
    }
    perm[0] = query;
  }
  return result;
}

