function processQueries(queries, m) {
  // Give every value a sort key; the list order is the order of the keys.
  const key = [0];
  for (let v = 1; v <= m; v++) key.push(v);
  const out = [];
  queries.forEach((q, i) => {
    let before = 0;
    for (let v = 1; v <= m; v++) if (key[v] < key[q]) before++;
    out.push(before);
    key[q] = -(i + 1);
  });
  return out;
}

