function generate(rand, size) {
  const m = size === 'large' ? 1000 - Math.floor(rand() * 3) : 1 + Math.floor(rand() * 8);
  const n = size === 'large' ? m : 1 + Math.floor(rand() * m);
  const pool = size === 'large' || rand() < 0.5 ? m : 1 + Math.floor(rand() * m);
  const queries = Array.from({ length: n }, () => 1 + Math.floor(rand() * pool));
  return [queries, m];
}
